[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-orthopedics",
  "answer": "비접촉성 무릎 꺾임(축구) 후 즉시 부종 + 힘 빠짐은 전방십자인대(ACL) 파열이 가장 전형적이지만, 신경혈관 손상·구획증후군·개방골절·탈구·고령 골절을 먼저 배제해야 합니다. 영상검사는 X-ray(골절·탈구 배제) → 필요 시 MRI(ACL·반월상 평가)이며, 이학적 검사는 건측과 비교한 Lachman·전방전위·pivot shift·Meniscal provocation test·무릎 완전 신전 확인을 시행합니다. 급성기에는 통증·경련으로 이학적 검사 신뢰도가 떨어지므로 급성기 검사에서 '정상'이라고 ACL 파열을 배제할 수 없습니다.",
  "red_flag": {
    "present": false,
    "items": []
  },
  "hypotheses": [
    {
      "name": "전방십자인대(ACL) 파열",
      "icd10": "S83.51",
      "must_not_miss": false,
      "probability_band": "high",
      "supports": [
        { "text": "비접촉성 감속·방향전환·축구 문맥의 전형적 손상 기전", "basis": "history" },
        { "text": "손상 직후 수 시간 내 급성 혈성 관절 부종(pop 후 즉시 붓기)", "basis": "history" },
        { "text": "'힘 빠짐'/giving-way — ACL 파열의 특징적 주소", "basis": "history" }
      ],
      "against": [
        { "text": "X-ray/이학적 소견이 아직 제공되지 않아 확정 불가", "basis": "history" }
      ]
    },
    {
      "name": "반월상연골 파열",
      "icd10": "S83.2",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "축구 중 비틀림 기전", "basis": "history" },
        { "text": "급성 관절 부종", "basis": "history" }
      ],
      "against": [
        { "text": "즉시 대량 부종은 혈관성(ACL 등) 손상 시 더 흔함; 반월상 단독은 지연성 부종·잠김 양상이 많음", "basis": "guideline" }
      ]
    },
    {
      "name": "무릎 골절(대퇴과·경골 고평부·슬개골·Segond 등)",
      "icd10": "S82.0–S82.9",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "무릎 비틀림 손상", "basis": "history" }
      ],
      "against": [
        { "text": "체중부하 여부·국소 압통·변형 소견이 아직 확인되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "무릎 탈구(슬관절 탈구) — 신경혈관 손상 동반 가능",
      "icd10": "S83.1",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "고에너지 비틀림 손상", "basis": "history" }
      ],
      "against": [
        { "text": "말단 맥박·감각·온도·색조 변화, 변형 여부 미확인 — [정형 규칙 1]대로 먼저 확인 필요", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "손상측 발등 맥박·발가락 감각·색·온도가 정상인지(신경혈관 상태) — 확인 안 되면 즉시 응급"
  ],
  "suggested_tests": [
    { "name": "무릎 X-ray (AP·lateral ± oblique, 필요 시 tunnel/sunrise view)", "purpose": "골절·탈구·Segond 골절 등 즉시 배제", "urgency": "now", "basis": "guideline" },
    { "name": "신경혈관 검사(발등맥박·발가락 감각·모세혈관 재충만·발가락 운동)", "purpose": "동맥·신경 손상 배제", "urgency": "now", "basis": "guideline" },
    { "name": "Lachman 검사(급성기라도 가장 민감)", "purpose": "ACL 파열 평가", "urgency": "24h", "basis": "guideline" },
    { "name": "전방전위 검사(Anterior drawer) + Pivot shift — 건측과 비교", "purpose": "ACL 기능 평가", "urgency": "24h", "basis": "guideline" },
    { "name": "McMurray / Thessaly / 관절선 압통", "purpose": "반월상 손상 평가", "urgency": "24h", "basis": "guideline" },
    { "name": "완전 신전 잠김 여부, 슬개골 압통·ballottement", "purpose": "잠김 반월상·슬개골 손상 감별", "urgency": "24h", "basis": "guideline" },
    { "name": "무릎 MRI", "purpose": "ACL·반월상·연골·골타박 정밀 평가(급성 통증·부종 가라앉은 뒤 또는 수술 계획 시)", "urgency": "routine", "basis": "guideline" }
  ],
  "suggested_treatments": [
    { "kind": "self_care", "description": "손상 부위 보호·안정, 필요 시 냉찜질(얼음은 수건 등으로 피부 보호, 15–20분 간격), 가능하면 거상, 통증 허용 범위에서 점진적 관절 운동. 체중부하는 통증·안정성에 따라 조절.", "basis": "guideline" },
    { "kind": "self_care", "description": "대퇴사두근 등척성 수축·수동적 무릎 굴곡-신전 운동은 급성 통증 조절 후 시작하는 일반적 원칙. 세부 프로토콜은 재활과·물리치료 평가 권장.", "basis": "guideline" },
    { "kind": "referral", "description": "정형외과 대면 평가(급성 혈성 관절 부종 + 힘 빠짐은 ACL 파열 의심으로 전문의 진찰·영상 판독 필요).", "basis": "guideline" }
  ],
  "handoff": { "better_specialty": "", "reason": "" },
  "confidence": { "clinical": 3, "information": 2 },
  "warnings": [
    "급성기(수 시간 내) 이학적 검사는 통증·근경련·혈종 때문에 위음성이 흔함 — 급성기 '정상 Lachman'을 ACL 파열 배제로 해석하지 말 것.",
    "O1(신경혈관 손상) 또는 O2(구획증후군)·O3(개방골절) 시사 소견이 나타나면 즉시 응급으로 회신할 것.",
    "고령·골다공증·스테로이드 사용·항응고제 복용 여부는 추가 확인 필요(이 질문엔 '성인'만 주어짐).",
    "MRI는 급성기 대신 X-ray 우선이 표준이며, 이학적 검사에서 잠김·불안정이 명확하면 MRI 전이라도 정형외과 대면 평가가 우선."
  ]
}
[/SPECIALIST_FINDING]

자기 점검: C1(해당 없음) / C2(모든 항목 basis 명시) / C3(확정 표현 없음) / C4(용량 서술 없음) — 위반 없음.

비고: 위 소견은 `guideline` basis로 표시했지만, 본 회신에서는 [WEB_SEARCH]로 개별 출처를 조회하지 않았으므로 **파라메트릭 기억에 기반한 일반 지식**에 해당합니다. 출처·조회일이 필요한 항목(예: Ottawa Knee Rule 등 특정 판별규칙 수치)은 별도 [WEB_SEARCH] 후 [출처 확인]으로 갱신해야 합니다.
